package com.sami.app.purchasing;
import com.sami.app.accounting.publicapi.PayablePostingPort; import com.sami.app.common.tenancy.TenantContext; import com.sami.app.organization.service.*; import com.sami.app.purchasing.service.SupplierInvoiceService; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.jdbc.core.JdbcTemplate; import java.math.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class SupplierInvoiceServiceBehaviorTest { @Mock JdbcTemplate jdbc; @Mock TenantContext tenants; @Mock OrganizationScopeService scope; @Mock FoundationAuditService audit; @Mock PayablePostingPort payable; SupplierInvoiceService service;
 @BeforeEach void setup(){service=new SupplierInvoiceService(jdbc,tenants,scope,audit,Optional.of(payable));when(tenants.requireTenantId()).thenReturn(7L);when(jdbc.queryForList(anyString(),eq(7L),eq(9L))).thenReturn(List.of());}
 @Test void alreadyIssuedIsIdempotent(){Map<String,Object> row=new HashMap<>(Map.of("status","ISSUED","company_id",1L,"branch_id",2L));when(jdbc.queryForMap(anyString(),eq(7L),eq(9L))).thenReturn(row);assertEquals("ISSUED",service.issue(9L).get("status"));verifyNoInteractions(payable);}
}
